UPDATE user_profile_identity
SET last_lender_request_json = #{requestJson},
    last_lender_response_json = #{responseJson}
WHERE profile_id = #{profileId}

UPDATE user_profile_identity
SET identity_data_retention_until = #{retentionUntil, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler},
    biometric_image_retention_until = #{retentionUntil, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE profile_id = #{profileId}
